using System.ComponentModel.DataAnnotations;

namespace Api.Core.Configuration;

/// <summary>
/// The API's own settings (section "Api"), bound and validated at startup: a missing or invalid value stops the app
/// before it serves a request. Read them through IOptions&lt;ApiOptions&gt;, never through IConfiguration in services.
/// </summary>
public sealed class ApiOptions
{
    public const string Section = "Api";

    [Required]
    public string ServiceName { get; init; } = string.Empty;
}

using Api.Core.Configuration;
using Api.Core.Errors;

namespace Api.Core;

public static class CoreFoundationExtensions
{
    /// <summary>Problem details for every error, validated typed settings and health checks.</summary>
    public static IServiceCollection AddCoreFoundation(this IServiceCollection services, IConfiguration configuration)
    {
        services.AddProblemDetails();
        services.AddExceptionHandler<AppExceptionHandler>();
        services.AddOptions<ApiOptions>()
            .Bind(configuration.GetSection(ApiOptions.Section))
            .ValidateDataAnnotations()
            .ValidateOnStart();
        services.AddHealthChecks();
        return services;
    }

    /// <summary>The exception handler first, problem details for bare status codes, and GET /health/ready.</summary>
    public static WebApplication UseCoreFoundation(this WebApplication app)
    {
        app.UseExceptionHandler();
        app.UseStatusCodePages();
        app.MapHealthChecks("/health/ready");
        return app;
    }
}

namespace Api.Core.Errors;

/// <summary>An expected failure with its HTTP status; AppExceptionHandler turns it into a problem details response.</summary>
public abstract class AppException(string message, int statusCode, string title) : Exception(message)
{
    public int StatusCode { get; } = statusCode;

    public string Title { get; } = title;
}

public sealed class InvalidInputException(string message) : AppException(message, StatusCodes.Status400BadRequest, "Invalid input");

public sealed class ForbiddenException(string message) : AppException(message, StatusCodes.Status403Forbidden, "Forbidden");

public sealed class NotFoundException(string entity, string id) : AppException($"{entity} {id} was not found.", StatusCodes.Status404NotFound, "Not found");

public sealed class ConflictException(string message) : AppException(message, StatusCodes.Status409Conflict, "Conflict");

using Microsoft.AspNetCore.Diagnostics;

namespace Api.Core.Errors;

/// <summary>
/// Every exception becomes an RFC 9457 problem details response. An AppException keeps its status and message; any
/// other exception is logged and answered with 500 and no internal detail.
/// </summary>
public sealed class AppExceptionHandler(IProblemDetailsService problemDetails, ILogger<AppExceptionHandler> logger) : IExceptionHandler
{
    public async ValueTask<bool> TryHandleAsync(HttpContext httpContext, Exception exception, CancellationToken cancellationToken)
    {
        var (status, title, detail) = exception is AppException app
            ? (app.StatusCode, app.Title, app.Message)
            : (StatusCodes.Status500InternalServerError, "An unexpected error occurred.", null);
        if (exception is not AppException)
        {
            logger.LogError(exception, "Unhandled exception for {Method} {Path}", httpContext.Request.Method, httpContext.Request.Path);
        }

        httpContext.Response.StatusCode = status;
        return await problemDetails.TryWriteAsync(new ProblemDetailsContext
        {
            HttpContext = httpContext,
            Exception = exception,
            ProblemDetails = { Status = status, Title = title, Detail = detail },
        });
    }
}

using Api.Core.Errors;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging.Abstractions;

namespace Api.Tests.Core;

public sealed class AppExceptionHandlerTests
{
    private static async Task<HttpContext> Handle(Exception exception)
    {
        var services = new ServiceCollection().AddLogging().AddProblemDetails().BuildServiceProvider();
        var context = new DefaultHttpContext { RequestServices = services };
        context.Response.Body = new MemoryStream();
        var handler = new AppExceptionHandler(services.GetRequiredService<IProblemDetailsService>(), NullLogger<AppExceptionHandler>.Instance);
        Assert.True(await handler.TryHandleAsync(context, exception, CancellationToken.None));
        return context;
    }

    private static string Body(HttpContext context)
    {
        context.Response.Body.Position = 0;
        return new StreamReader(context.Response.Body).ReadToEnd();
    }

    [Fact]
    public async Task An_app_exception_keeps_its_status_and_message()
    {
        var context = await Handle(new NotFoundException("Order", "42"));

        Assert.Equal(StatusCodes.Status404NotFound, context.Response.StatusCode);
        Assert.Contains("Order 42 was not found.", Body(context));
    }

    [Fact]
    public async Task Any_other_exception_is_a_500_without_its_message()
    {
        var context = await Handle(new InvalidOperationException("connection string secret"));

        Assert.Equal(StatusCodes.Status500InternalServerError, context.Response.StatusCode);
        Assert.DoesNotContain("connection string secret", Body(context));
    }
}

