abstract class Failure {
  final String message;
  final String? code;
  final Object? cause;

  const Failure(this.message, {this.code, this.cause});

  @override
  String toString() => 'Failure(message: $message, code: $code)';
}

class ServerFailure extends Failure {
  const ServerFailure(super.message, {super.code, super.cause});
}

class StorageFailure extends Failure {
  const StorageFailure(super.message, {super.code, super.cause});
}

class ValidationFailure extends Failure {
  const ValidationFailure(super.message, {super.code, super.cause});
}

class UnexpectedFailure extends Failure {
  const UnexpectedFailure([super.message = 'An unexpected error occurred', Object? cause]) : super(cause: cause);
}

import 'package:{{PACKAGE_NAME}}/core/errors/failures.dart';

sealed class Result<T> {
  const Result();

  factory Result.success(T data) = Success<T>;
  factory Result.failure(Failure failure) = Error<T>;

  bool get isSuccess => this is Success<T>;
  bool get isFailure => this is Error<T>;

  T? get dataOrNull => switch (this) {
    Success(:final data) => data,
    Error() => null,
  };

  Failure? get failureOrNull => switch (this) {
    Success() => null,
    Error(:final failure) => failure,
  };

  R when<R>({
    required R Function(T data) success,
    required R Function(Failure failure) failure,
  }) {
    return switch (this) {
      Success(:final data) => success(data),
      Error(failure: final error) => failure(error),
    };
  }
}

final class Success<T> extends Result<T> {
  final T data;
  const Success(this.data);
}

final class Error<T> extends Result<T> {
  final Failure failure;
  const Error(this.failure);
}

import 'dart:developer' as developer;
import 'package:flutter/foundation.dart';

enum LogLevel { debug, info, warning, error }

class LogHelper {
  static void debug(String message, {String tag = 'APP'}) => _log(LogLevel.debug, message, tag: tag);
  static void info(String message, {String tag = 'APP'}) => _log(LogLevel.info, message, tag: tag);
  static void warning(String message, {String tag = 'APP'}) => _log(LogLevel.warning, message, tag: tag);
  static void error(String message, {Object? error, StackTrace? stackTrace, String tag = 'APP'}) {
    _log(LogLevel.error, message, tag: tag, error: error, stackTrace: stackTrace);
  }

  static void _log(LogLevel level, String message, {String tag = 'APP', Object? error, StackTrace? stackTrace}) {
    if (kDebugMode) {
      final color = switch (level) {
        LogLevel.debug => '\x1B[34m',
        LogLevel.info => '\x1B[32m',
        LogLevel.warning => '\x1B[33m',
        LogLevel.error => '\x1B[31m',
      };
      developer.log('$color[${level.name.toUpperCase()}][$tag] $message\x1B[0m', error: error, stackTrace: stackTrace);
    }
  }
}

