import { AppError } from '../errors/AppError';

export type ServiceResult<T, E extends Error = AppError> = ResultOk<T> | ResultFail<E>;

export class ResultOk<T> {
  public readonly isSuccess = true;
  public readonly isFailure = false;

  constructor(public readonly data: T) {}

  public get dataOrNull(): T {
    return this.data;
  }

  public get errorOrNull(): null {
    return null;
  }

  public map<U>(fn: (data: T) => U): ServiceResult<U, any> {
    return new ResultOk(fn(this.data));
  }

  public flatMap<U, E extends Error>(fn: (data: T) => ServiceResult<U, E>): ServiceResult<U, E> {
    return fn(this.data);
  }

  public when<R>(matchers: { success: (data: T) => R; failure: (error: any) => R }): R {
    return matchers.success(this.data);
  }
}

export class ResultFail<E extends Error = AppError> {
  public readonly isSuccess = false;
  public readonly isFailure = true;

  constructor(public readonly error: E) {}

  public get dataOrNull(): null {
    return null;
  }

  public get errorOrNull(): E {
    return this.error;
  }

  public map<U>(_fn: (data: any) => U): ServiceResult<U, E> {
    return this as any;
  }

  public flatMap<U>(_fn: (data: any) => ServiceResult<U, any>): ServiceResult<U, E> {
    return this as any;
  }

  public when<R>(matchers: { success: (data: any) => R; failure: (error: E) => R }): R {
    return matchers.failure(this.error);
  }
}

export function ok<T>(data: T): ResultOk<T> {
  return new ResultOk(data);
}

export function fail<E extends Error>(error: E): ResultFail<E> {
  return new ResultFail(error);
}

export class FeatureFlags {
  private static flags: Map<string, boolean> = new Map();

  public static initialize(initialFlags: Record<string, boolean> = {}): void {
    this.flags = new Map(Object.entries(initialFlags));
  }

  public static isEnabled(flagName: string): boolean {
    // If explicitly set in process.env (e.g. FEATURE_USE_V2_AUTH=true), that takes precedence
    const envKey = `FEATURE_${flagName}`;
    if (process.env[envKey] !== undefined) {
      return process.env[envKey] === 'true' || process.env[envKey] === '1';
    }
    return this.flags.get(flagName) === true;
  }

  public static setFlag(flagName: string, enabled: boolean): void {
    this.flags.set(flagName, enabled);
  }

  public static getAll(): Record<string, boolean> {
    const res: Record<string, boolean> = {};
    this.flags.forEach((value, key) => {
      res[key] = value;
    });
    return res;
  }

  public static async executeBranch<T>({
    flagName,
    modern,
    legacy,
    onShadowMismatch
  }: {
    flagName: string;
    modern: () => Promise<T>;
    legacy: () => Promise<T>;
    onShadowMismatch?: (legacyRes: any, modernRes: any) => void;
  }): Promise<T> {
    const isV2 = this.isEnabled(flagName);
    const isShadow = this.isEnabled(`SHADOW_${flagName}`);

    if (isShadow) {
      const [legacyResult, modernResult] = await Promise.allSettled([legacy(), modern()]);
      if (legacyResult.status !== modernResult.status && onShadowMismatch) {
        onShadowMismatch(legacyResult, modernResult);
      }
      if (legacyResult.status === 'fulfilled') {
        return legacyResult.value;
      }
      throw (legacyResult as PromiseRejectedResult).reason;
    }

    return isV2 ? modern() : legacy();
  }
}

/**
 * Canonical Enterprise Environment Names.
 * Mapped from industry standards across cloud providers (AWS, GCP, Vercel).
 */
export type EnvironmentName = 'dev' | 'test' | 'staging' | 'prod' | 'demo';

function resolveEnvironmentName(): EnvironmentName {
  const raw = (process.env.NODE_ENV || '').toLowerCase().trim();
  switch (raw) {
    case 'prod':
    case 'production':
      return 'prod';
    case 'staging':
    case 'stage':
    case 'preprod':
    case 'uat':
      return 'staging';
    case 'test':
    case 'testing':
    case 'ci':
      return 'test';
    case 'demo':
    case 'sandbox':
      return 'demo';
    case 'dev':
    case 'development':
    default:
      return 'dev';
  }
}

const envName = resolveEnvironmentName();

/**
 * Single Source of Truth (SSOT) Application Configuration.
 * MANDATE: process.env must NEVER be accessed directly anywhere else in the codebase.
 * NOTE: Do not populate arbitrary speculative sample keys here; only declare real,
 * typed platform parameters and lifecycle flags.
 */
export const appConfig = {
  envName,
  isDev: envName === 'dev',
  isTest: envName === 'test',
  isStaging: envName === 'staging',
  isProd: envName === 'prod',
  isDemo: envName === 'demo',
  isEmulator: process.env.FUNCTIONS_EMULATOR === 'true',
  isDryRun: process.env.DRY_RUN === 'true' || envName === 'demo',
  port: parseInt(process.env.PORT || '{{DEFAULT_PORT}}', 10),
  appUrl: process.env.APP_URL || 'http://localhost:3000'
} as const;

export type AppConfig = typeof appConfig;

export enum LogLevel {
  DEBUG = 'DEBUG',
  INFO = 'INFO',
  WARN = 'WARN',
  ERROR = 'ERROR'
}

export interface LogContext {
  correlationId?: string;
  userId?: string;
  tenantId?: string;
  module?: string;
  [key: string]: any;
}

export class Logger {
  private static currentContext: LogContext = {};

  public static setGlobalContext(ctx: LogContext): void {
    this.currentContext = { ...this.currentContext, ...ctx };
  }

  public static debug(message: string, meta?: Record<string, any>): void {
    this.log(LogLevel.DEBUG, message, meta);
  }

  public static info(message: string, meta?: Record<string, any>): void {
    this.log(LogLevel.INFO, message, meta);
  }

  public static warn(message: string, meta?: Record<string, any>): void {
    this.log(LogLevel.WARN, message, meta);
  }

  public static error(message: string, error?: any, meta?: Record<string, any>): void {
    const errorDetails = error instanceof Error ? {
      name: error.name,
      message: error.message,
      stack: error.stack
    } : error;

    this.log(LogLevel.ERROR, message, { ...meta, error: errorDetails });
  }

  private static log(level: LogLevel, message: string, meta?: Record<string, any>): void {
    const entry = {
      timestamp: new Date().toISOString(),
      level,
      message,
      context: { ...this.currentContext, ...meta }
    };

    if (process.env.NODE_ENV === 'production' || process.env.NODE_ENV === 'prod') {
      process.stdout.write(JSON.stringify(entry) + '\n');
    } else {
      const color = level === LogLevel.ERROR ? '\x1b[31m' : level === LogLevel.WARN ? '\x1b[33m' : level === LogLevel.INFO ? '\x1b[32m' : '\x1b[36m';
      const metaStr = meta && Object.keys(meta).length > 0 ? ` ${JSON.stringify(meta)}` : '';
      process.stdout.write(`${color}[${entry.timestamp}] [${level}]\x1b[0m ${message}${metaStr}\n`);
    }
  }
}

import { Request } from 'express';
import * as admin from 'firebase-admin';
import { UnauthorizedError } from '../../errors/AppError';

export class AppCheckValidator {
  /**
   * Validates Firebase App Check token from request headers.
   * Enforces device attestation (Play Integrity / App Attest) to block scrapers.
   */
  public static async validateAppCheck(request: Request, appId?: number): Promise<void> {
    // Allow bypassing in local dev/demo environments if configured
    if (process.env.APP_CHECK_DISABLED === 'true') {
      return;
    }

    const appCheckToken = (request.headers['x-firebase-appcheck'] as string) || (request.headers['X-Firebase-AppCheck'] as string);
    if (!appCheckToken || !appCheckToken.trim()) {
      throw new UnauthorizedError('Firebase App Check token is required for device verification');
    }

    try {
      if (admin.apps.length === 0) {
        admin.initializeApp();
      }
      const appCheckClaims = await admin.appCheck().verifyToken(appCheckToken);
      (request as any).appCheck = appCheckClaims;
    } catch (error: any) {
      throw new UnauthorizedError(`App Check token verification failed: ${error.message}`);
    }
  }
}

import crypto from 'crypto';
import { Request } from 'express';
import { UnauthorizedError } from '../../errors/AppError';

export interface HmacVerificationOptions {
  secretKey?: string;
  toleranceSeconds?: number;
}

export class HmacSignatureVerifier {
  private static readonly DEFAULT_TOLERANCE_SECONDS = 300; // 5 minutes

  /**
   * Verifies incoming request HMAC-SHA256 signature and timestamp freshness window.
   */
  public static verify(request: Request, options: HmacVerificationOptions = {}): void {
    const signature = (request.headers['x-signature'] as string) || (request.headers['X-Signature'] as string);
    const timestamp = (request.headers['x-timestamp'] as string) || (request.headers['X-Timestamp'] as string);

    if (!signature || !timestamp) {
      throw new UnauthorizedError('HMAC signature and timestamp headers (x-signature, x-timestamp) are required');
    }

    // 1. Anti-Replay: Check timestamp freshness
    const reqTime = parseInt(timestamp, 10);
    const now = Math.floor(Date.now() / 1000);
    const tolerance = options.toleranceSeconds || this.DEFAULT_TOLERANCE_SECONDS;

    if (isNaN(reqTime) || Math.abs(now - reqTime) > tolerance) {
      throw new UnauthorizedError('Request signature timestamp expired or out of allowed window');
    }

    // 2. Compute expected HMAC hash: METHOD + PATH + TIMESTAMP + BODY
    const secret = options.secretKey || process.env.HMAC_SECRET_KEY;
    if (!secret) {
      throw new Error('HMAC_SECRET_KEY is not set: the HMAC signature guard needs the shared signing secret.');
    }
    const method = (request.method || 'GET').toUpperCase();
    const path = request.originalUrl || request.url || '/';
    const bodyString = request.body ? (typeof request.body === 'string' ? request.body : JSON.stringify(request.body)) : '';

    const payloadToSign = `${method}:${path}:${timestamp}:${bodyString}`;
    const expectedSignature = crypto
      .createHmac('sha256', secret)
      .update(payloadToSign)
      .digest('hex');

    // 3. Constant-time comparison to prevent timing attacks
    const sigBuffer = Buffer.from(signature, 'hex');
    const expectedBuffer = Buffer.from(expectedSignature, 'hex');

    if (sigBuffer.length !== expectedBuffer.length || !crypto.timingSafeEqual(sigBuffer, expectedBuffer)) {
      throw new UnauthorizedError('HMAC request signature verification failed: Payload was tampered or invalid secret');
    }
  }
}

export interface TenantInfo {
  id: string;
  name: string;
  appId?: number;
  user?: any;
  userState?: any;
  [key: string]: any;
}

export interface AdminTokenPayload {
  id: string;
  email: string;
  roles: string[];
  tenantId?: string;
}

export interface DecodedAuthToken {
  uid: string;
  email?: string;
  [key: string]: any;
}

import { Request } from 'express';
import * as admin from 'firebase-admin';
import { ForbiddenError, UnauthorizedError } from '../errors/AppError';
import { TenantInfo, AdminTokenPayload, DecodedAuthToken } from './AuthModels';
import { ITenantInfoProvider } from './ITenantInfoProvider';

let tenantInfoProviderInstance: ITenantInfoProvider | null = null;

export function setTenantInfoProvider(provider: ITenantInfoProvider): void {
  tenantInfoProviderInstance = provider;
}

function bearerToken(request: Request): string {
  const header = request.headers.authorization;
  const token = header?.startsWith('Bearer ') ? header.slice('Bearer '.length).trim() : '';
  if (!token) {
    throw new UnauthorizedError('Bearer authorization token required');
  }
  return token;
}

async function verifyFirebaseToken(request: Request): Promise<DecodedAuthToken> {
  const token = bearerToken(request);
  try {
    if (admin.apps.length === 0) {
      admin.initializeApp();
    }
    return await admin.auth().verifyIdToken(token);
  } catch (error: any) {
    throw new UnauthorizedError(`Firebase token verification failed: ${error.message}`);
  }
}

/** Admin endpoints: a verified Firebase token whose `roles` custom claim holds every required scope ('admin' when none is given). */
async function authenticateAdmin(request: Request, scopes?: string[]): Promise<AdminTokenPayload> {
  const decodedToken = await verifyFirebaseToken(request);
  const roles: string[] = Array.isArray(decodedToken.roles) ? decodedToken.roles : [];
  const required = scopes && scopes.length ? scopes : ['admin'];
  const missing = required.filter((role) => !roles.includes(role));
  if (missing.length) {
    throw new ForbiddenError(`Missing admin role(s): ${missing.join(', ')}`);
  }
  return { id: decodedToken.uid, email: decodedToken.email ?? '', roles };
}

/** App users: a verified Firebase token, resolved to its tenant by the provider set at startup. */
async function authenticateTenant(request: Request): Promise<TenantInfo> {
  if (!tenantInfoProviderInstance) {
    throw new Error('No tenant info provider: call setTenantInfoProvider() in createServer (src/server.ts).');
  }
  const appId = Number(request.headers['x-app-id']) || 1;
  const decodedToken = await verifyFirebaseToken(request);
  return tenantInfoProviderInstance.initializeTenantInfo(appId, decodedToken);
}

/**
 * TSOA expressAuthentication hook: `@Security('firebase')` for app users, `@Security('admin_rbac', [roles])` for admins.
 * The resolved identity is attached to request.user, so controllers never read tokens.
 */
export async function expressAuthentication(
  request: Request,
  securityName: string,
  scopes?: string[]
): Promise<TenantInfo | AdminTokenPayload> {
  let user: TenantInfo | AdminTokenPayload;
  if (securityName === 'admin_rbac') {
    user = await authenticateAdmin(request, scopes);
  } else if (securityName === 'firebase') {
    user = await authenticateTenant(request);
  } else {
    throw new UnauthorizedError(`Unknown authentication scheme: ${securityName}`);
  }
  (request as any).user = user;
  return user;
}

export * from './AuthModels';
export * from './ITenantInfoProvider';
export * from './TokenTenantInfoProvider';
export * from './expressAuthentication';

import { DecodedAuthToken, TenantInfo } from './AuthModels';

export interface ITenantInfoProvider {
  initializeTenantInfo(appId: number, decodedToken: DecodedAuthToken): Promise<TenantInfo>;
}

import { DecodedAuthToken, TenantInfo } from './AuthModels';
import { ITenantInfoProvider } from './ITenantInfoProvider';

/** The signed-in Firebase user is the tenant. Replace it with the project's own provider once tenants are stored records. */
export class TokenTenantInfoProvider implements ITenantInfoProvider {
  public async initializeTenantInfo(appId: number, decodedToken: DecodedAuthToken): Promise<TenantInfo> {
    return {
      id: decodedToken.uid,
      name: decodedToken.email ?? decodedToken.uid,
      appId,
      user: { id: decodedToken.uid, email: decodedToken.email }
    };
  }
}

import mongoose from 'mongoose';
import { z } from 'zod';
import { IEntityBase, EntityStatus } from './EntityBase';
import { FindByModel, FilterQuery, PaginationOptions, LookupOptions, WhereFilterOperator } from './QueryModels';
import { IGenericRepository } from './IGenericRepository';
import { NotFoundError, ValidationError, DatabaseError } from '../errors/AppError';

export interface RepositoryOptions<T> {
  softDelete?: boolean;
  softDeleteField?: string;
  validator?: z.ZodSchema<T>;
}

/** A stored document: entities keep their string id in `_id`. */
type MongoDoc = mongoose.mongo.Document & { _id: string };

export class BaseMongoRepository<T extends IEntityBase> implements IGenericRepository<T> {
  protected readonly collectionName: string;
  protected readonly options: Required<RepositoryOptions<T>>;

  constructor(collectionName: string, options: RepositoryOptions<T> = {}) {
    this.collectionName = collectionName;
    this.options = {
      softDelete: options.softDelete ?? false,
      softDeleteField: options.softDeleteField ?? 'status',
      validator: options.validator as any
    };
  }

  protected async getCollection(): Promise<mongoose.mongo.Collection<MongoDoc>> {
    if (!mongoose.connection.db) {
      throw new DatabaseError(`MongoDB connection is not established. Cannot access collection '${this.collectionName}'`);
    }
    return mongoose.connection.db.collection<MongoDoc>(this.collectionName);
  }

  protected toMongoDoc(data: any): any {
    const { id, _id, ...rest } = data;
    const targetId = id || _id || new mongoose.Types.ObjectId().toHexString();
    return {
      _id: targetId,
      ...rest
    };
  }

  protected fromMongoDoc(doc: any): T | null {
    if (!doc) return null;
    const { _id, ...rest } = doc;
    return {
      id: typeof _id === 'object' && _id !== null ? _id.toString() : String(_id),
      ...rest
    } as T;
  }

  protected applySoftDeleteFilter(filter: any): any {
    if (this.options.softDelete) {
      filter[this.options.softDeleteField] = { $ne: EntityStatus.Deleted };
    }
    return filter;
  }

  protected convertOperator(opStr: WhereFilterOperator, value: any): any {
    switch (opStr) {
      case '==': return value;
      case '!=': return { $ne: value };
      case '>': return { $gt: value };
      case '>=': return { $gte: value };
      case '<': return { $lt: value };
      case '<=': return { $lte: value };
      case 'in': return { $in: value };
      case 'not-in': return { $nin: value };
      case 'array-contains': return { $elemMatch: { $eq: value } };
      case 'regex': return { $regex: value, $options: 'i' };
      case 'exists': return { $exists: true };
      case 'not-exists': return { $exists: false };
      default: return value;
    }
  }

  protected validate(data: any): void {
    if (this.options.validator) {
      const result = this.options.validator.safeParse(data);
      if (!result.success) {
        throw new ValidationError(`Validation failed for '${this.collectionName}'`, result.error.format());
      }
    }
  }

  public async create(data: Partial<T>): Promise<T> {
    this.validate(data);
    const collection = await this.getCollection();
    const now = new Date();
    const entryObject: any = {
      ...data,
      createdAt: now,
      updatedAt: now,
      id: data.id || new mongoose.Types.ObjectId().toHexString()
    };

    if (this.options.softDelete && entryObject[this.options.softDeleteField] === undefined) {
      entryObject[this.options.softDeleteField] = EntityStatus.Active;
    }

    const mongoDoc = this.toMongoDoc(entryObject);
    const res = await collection.insertOne(mongoDoc);
    if (!res.acknowledged) {
      throw new DatabaseError(`Failed to insert document into '${this.collectionName}'`);
    }
    return this.fromMongoDoc(mongoDoc)!;
  }

  public async bulkCreate(data: Partial<T>[]): Promise<T[]> {
    const collection = await this.getCollection();
    const now = new Date();
    const entries: T[] = [];
    const mongoEntries: any[] = [];

    for (const item of data) {
      this.validate(item);
      const entryObject: any = {
        ...item,
        createdAt: now,
        updatedAt: now,
        id: item.id || new mongoose.Types.ObjectId().toHexString()
      };
      if (this.options.softDelete && entryObject[this.options.softDeleteField] === undefined) {
        entryObject[this.options.softDeleteField] = EntityStatus.Active;
      }
      mongoEntries.push(this.toMongoDoc(entryObject));
      entries.push(entryObject as T);
    }

    if (mongoEntries.length > 0) {
      const res = await collection.insertMany(mongoEntries);
      if (!res.acknowledged) {
        throw new DatabaseError(`Failed to bulk insert into '${this.collectionName}'`);
      }
    }
    return entries;
  }

  public async get(id: string): Promise<T | null> {
    const collection = await this.getCollection();
    const filter: any = { _id: id };
    this.applySoftDeleteFilter(filter);
    const doc = await collection.findOne(filter);
    return this.fromMongoDoc(doc);
  }

  public async getBy(params: FindByModel[]): Promise<T | null> {
    const collection = await this.getCollection();
    const filter: any = {};
    this.applySoftDeleteFilter(filter);
    for (const param of params) {
      const fieldName = param.fieldPath === 'id' ? '_id' : param.fieldPath;
      filter[fieldName] = this.convertOperator(param.opStr, param.value);
    }
    const doc = await collection.findOne(filter);
    return this.fromMongoDoc(doc);
  }

  public async list(pagination?: PaginationOptions): Promise<T[]> {
    const collection = await this.getCollection();
    const filter: any = {};
    this.applySoftDeleteFilter(filter);
    let cursor = collection.find(filter);

    if (pagination?.offset && pagination.offset > 0) cursor = cursor.skip(pagination.offset);
    if (pagination?.limit && pagination.limit > 0) cursor = cursor.limit(pagination.limit);

    if (pagination?.orderBy) {
      const dir = pagination.orderDirection === 'asc' ? 1 : -1;
      cursor = cursor.sort({ [pagination.orderBy]: dir });
    } else {
      cursor = cursor.sort({ _id: -1 });
    }

    const docs = await cursor.toArray();
    return docs.map(d => this.fromMongoDoc(d)!);
  }

  public async find(filterQueries: FilterQuery[], pagination?: PaginationOptions): Promise<T[]> {
    const collection = await this.getCollection();
    const filter: any = {};
    this.applySoftDeleteFilter(filter);

    for (const filterQuery of filterQueries) {
      const conditions = filterQuery.filters.map(param => {
        const fieldName = param.fieldPath === 'id' ? '_id' : param.fieldPath;
        return { [fieldName]: this.convertOperator(param.opStr, param.value) };
      });
      if (filterQuery.operator === 'AND' && conditions.length > 0) {
        filter.$and = filter.$and ? [...filter.$and, ...conditions] : conditions;
      } else if (filterQuery.operator === 'OR' && conditions.length > 0) {
        filter.$or = filter.$or ? [...filter.$or, ...conditions] : conditions;
      }
    }

    let cursor = collection.find(filter);
    if (pagination?.offset && pagination.offset > 0) cursor = cursor.skip(pagination.offset);
    if (pagination?.limit && pagination.limit > 0) cursor = cursor.limit(pagination.limit);
    if (pagination?.orderBy) {
      const dir = pagination.orderDirection === 'asc' ? 1 : -1;
      cursor = cursor.sort({ [pagination.orderBy]: dir });
    } else {
      cursor = cursor.sort({ _id: -1 });
    }

    const docs = await cursor.toArray();
    return docs.map(d => this.fromMongoDoc(d)!);
  }

  public async findBy(params: FindByModel[], pagination?: PaginationOptions): Promise<T[]> {
    return this.find([{ operator: 'AND', filters: params }], pagination);
  }

  public async findByPartial(params: FindByModel[], fields: string[], pagination?: PaginationOptions): Promise<Partial<T>[]> {
    const collection = await this.getCollection();
    const filter: any = {};
    this.applySoftDeleteFilter(filter);
    for (const param of params) {
      const fieldName = param.fieldPath === 'id' ? '_id' : param.fieldPath;
      filter[fieldName] = this.convertOperator(param.opStr, param.value);
    }

    const projection: Record<string, number> = {};
    for (const f of fields) {
      const key = f === 'id' ? '_id' : f;
      projection[key] = 1;
    }

    let cursor = collection.find(filter, { projection });
    if (pagination?.offset && pagination.offset > 0) cursor = cursor.skip(pagination.offset);
    if (pagination?.limit && pagination.limit > 0) cursor = cursor.limit(pagination.limit);
    if (pagination?.orderBy) {
      const dir = pagination.orderDirection === 'asc' ? 1 : -1;
      cursor = cursor.sort({ [pagination.orderBy]: dir });
    } else {
      cursor = cursor.sort({ _id: -1 });
    }

    const docs = await cursor.toArray();
    return docs.map(d => this.fromMongoDoc(d) as Partial<T>);
  }

  public async update(data: T, createIfNonExist: boolean = false): Promise<void> {
    this.validate(data);
    const collection = await this.getCollection();
    const filter: any = { _id: data.id };
    this.applySoftDeleteFilter(filter);

    const existing = await collection.findOne(filter);
    if (!existing) {
      if (!createIfNonExist) {
        throw new NotFoundError(this.collectionName, data.id);
      }
      await this.create(data);
      return;
    }

    const { id, _id, ...setFields } = this.toMongoDoc(data);
    setFields.updatedAt = new Date();
    const res = await collection.updateOne(filter, { $set: setFields });
    if (res.matchedCount === 0) {
      throw new NotFoundError(this.collectionName, data.id);
    }
  }

  public async updatePartial(id: string, updates: Partial<T>): Promise<void> {
    const collection = await this.getCollection();
    const filter: any = { _id: id };
    this.applySoftDeleteFilter(filter);

    const rawUpdates = { ...updates } as Record<string, any>;
    delete rawUpdates.id;
    delete rawUpdates._id;
    rawUpdates.updatedAt = new Date();

    const res = await collection.updateOne(filter, { $set: rawUpdates });
    if (res.matchedCount === 0) {
      throw new NotFoundError(this.collectionName, id);
    }
  }

  public async updateBy(params: FindByModel[], data: Record<string, any>): Promise<number> {
    const collection = await this.getCollection();
    const filter: any = {};
    this.applySoftDeleteFilter(filter);
    for (const param of params) {
      const fieldName = param.fieldPath === 'id' ? '_id' : param.fieldPath;
      filter[fieldName] = this.convertOperator(param.opStr, param.value);
    }
    const res = await collection.updateMany(filter, { $set: { ...data, updatedAt: new Date() } });
    return res.modifiedCount;
  }

  public async incrementBy(params: FindByModel[] | null, increments: Record<string, number>): Promise<number> {
    const collection = await this.getCollection();
    const filter: any = {};
    this.applySoftDeleteFilter(filter);
    if (params) {
      for (const param of params) {
        const fieldName = param.fieldPath === 'id' ? '_id' : param.fieldPath;
        filter[fieldName] = this.convertOperator(param.opStr, param.value);
      }
    }
    const res = await collection.updateMany(filter, { $inc: increments });
    return res.modifiedCount;
  }

  public async delete(id: string): Promise<T | null> {
    const collection = await this.getCollection();
    const filter: any = { _id: id };
    this.applySoftDeleteFilter(filter);

    const existing = await collection.findOne(filter);
    if (!existing) {
      throw new NotFoundError(this.collectionName, id);
    }

    if (this.options.softDelete) {
      await collection.updateOne({ _id: id }, {
        $set: {
          [this.options.softDeleteField]: EntityStatus.Deleted,
          deletedAt: new Date()
        }
      });
      return this.fromMongoDoc({ ...existing, [this.options.softDeleteField]: EntityStatus.Deleted });
    } else {
      await collection.deleteOne({ _id: id });
      return this.fromMongoDoc(existing);
    }
  }

  public async deleteBy(params: FindByModel[]): Promise<number> {
    const collection = await this.getCollection();
    const filter: any = {};
    for (const param of params) {
      const fieldName = param.fieldPath === 'id' ? '_id' : param.fieldPath;
      filter[fieldName] = this.convertOperator(param.opStr, param.value);
    }

    if (this.options.softDelete) {
      const res = await collection.updateMany(filter, {
        $set: {
          [this.options.softDeleteField]: EntityStatus.Deleted,
          deletedAt: new Date()
        }
      });
      return res.modifiedCount;
    } else {
      const res = await collection.deleteMany(filter);
      return res.deletedCount;
    }
  }

  public async count(params: FindByModel[] = []): Promise<number> {
    const collection = await this.getCollection();
    const filter: any = {};
    this.applySoftDeleteFilter(filter);
    for (const param of params) {
      const fieldName = param.fieldPath === 'id' ? '_id' : param.fieldPath;
      filter[fieldName] = this.convertOperator(param.opStr, param.value);
    }
    return collection.countDocuments(filter);
  }

  public async textSearch(searchTerm: string, offset: number = 0, limit: number = 20): Promise<T[]> {
    const collection = await this.getCollection();
    const filter: any = { $text: { $search: searchTerm } };
    this.applySoftDeleteFilter(filter);
    let cursor = collection.find(filter).skip(offset);
    if (limit > 0) cursor = cursor.limit(limit);
    const docs = await cursor.toArray();
    return docs.map(d => this.fromMongoDoc(d)!);
  }

  public async lookup(options: LookupOptions): Promise<any[]> {
    const collection = await this.getCollection();
    const matchStage: any = {};
    this.applySoftDeleteFilter(matchStage);

    if (options.filters && options.filters.length > 0) {
      for (const filter of options.filters) {
        const fieldName = filter.fieldPath === 'id' ? '_id' : filter.fieldPath;
        matchStage[fieldName] = this.convertOperator(filter.opStr, filter.value);
      }
    }

    const local = options.localField === 'id' ? '_id' : options.localField;
    const foreign = options.foreignField === 'id' ? '_id' : options.foreignField;

    const pipeline: any[] = [];
    if (Object.keys(matchStage).length > 0) pipeline.push({ $match: matchStage });
    pipeline.push({
      $lookup: {
        from: options.foreignCollection,
        localField: local,
        foreignField: foreign,
        as: options.asField
      }
    });

    if (options.offset && options.offset > 0) pipeline.push({ $skip: options.offset });
    if (options.limit && options.limit > 0) pipeline.push({ $limit: options.limit });

    const results = await collection.aggregate(pipeline).toArray();
    return results.map(doc => this.fromMongoDoc(doc));
  }

  public async lookupOne(options: LookupOptions): Promise<any[]> {
    const collection = await this.getCollection();
    const matchStage: any = {};
    this.applySoftDeleteFilter(matchStage);

    if (options.filters && options.filters.length > 0) {
      for (const filter of options.filters) {
        const fieldName = filter.fieldPath === 'id' ? '_id' : filter.fieldPath;
        matchStage[fieldName] = this.convertOperator(filter.opStr, filter.value);
      }
    }

    const local = options.localField === 'id' ? '_id' : options.localField;
    const foreign = options.foreignField === 'id' ? '_id' : options.foreignField;

    const pipeline: any[] = [];
    if (Object.keys(matchStage).length > 0) pipeline.push({ $match: matchStage });
    pipeline.push({
      $lookup: {
        from: options.foreignCollection,
        localField: local,
        foreignField: foreign,
        as: options.asField
      }
    });
    pipeline.push({
      $unwind: {
        path: `$${options.asField}`,
        preserveNullAndEmptyArrays: false
      }
    });

    if (options.offset && options.offset > 0) pipeline.push({ $skip: options.offset });
    if (options.limit && options.limit > 0) pipeline.push({ $limit: options.limit });

    const results = await collection.aggregate(pipeline).toArray();
    return results.map(doc => this.fromMongoDoc(doc));
  }
}

