import { IEntityBase, ITenantScoped, TenantInfo } from './EntityBase';
import { BaseMongoRepository, RepositoryOptions } from './BaseMongoRepository';
import { FindByModel, FilterQuery, PaginationOptions, LookupOptions } from './QueryModels';
import { UnauthorizedError } from '../errors/AppError';

export class TenantMongoRepository<T extends IEntityBase & ITenantScoped> extends BaseMongoRepository<T> {
  protected readonly tenant: TenantInfo;

  constructor(collectionName: string, tenant: TenantInfo, options: RepositoryOptions<T> = {}) {
    super(collectionName, options);
    if (!tenant || !tenant.id) {
      throw new UnauthorizedError('TenantContext is mandatory for TenantMongoRepository.');
    }
    this.tenant = tenant;
  }

  public get tenantId(): string {
    return this.tenant.id;
  }

  protected applyTenantFilter(filter: any): any {
    filter.tenantId = this.tenant.id;
    return filter;
  }

  protected override applySoftDeleteFilter(filter: any): any {
    super.applySoftDeleteFilter(filter);
    return this.applyTenantFilter(filter);
  }

  public override async create(data: Partial<T>): Promise<T> {
    const tenantData = {
      ...data,
      tenantId: this.tenant.id
    };
    return super.create(tenantData);
  }

  public override async bulkCreate(data: Partial<T>[]): Promise<T[]> {
    const tenantData = data.map(item => ({
      ...item,
      tenantId: this.tenant.id
    }));
    return super.bulkCreate(tenantData);
  }

  public override async updatePartial(id: string, updates: Partial<T>): Promise<void> {
    const cleanUpdates = { ...updates };
    delete (cleanUpdates as any).tenantId;
    return super.updatePartial(id, cleanUpdates);
  }

  public override async lookup(options: LookupOptions): Promise<any[]> {
    const tenantFilters = [
      ...(options.filters || []),
      new FindByModel('tenantId', '==', this.tenant.id)
    ];
    return super.lookup({ ...options, filters: tenantFilters });
  }

  public override async lookupOne(options: LookupOptions): Promise<any[]> {
    const tenantFilters = [
      ...(options.filters || []),
      new FindByModel('tenantId', '==', this.tenant.id)
    ];
    return super.lookupOne({ ...options, filters: tenantFilters });
  }
}

import { PiiMasker } from './PiiMasker';

export interface ComparisonResult {
  matches: boolean;
  statusMatch: boolean;
  differences: string[];
}

export interface CharacterizationOptions {
  ignoredKeys?: string[];
  maskPii?: boolean;
  dryRun?: boolean;
}

export class CharacterizationHarness {
  private static defaultIgnoredKeys = new Set([
    'timestamp',
    'createdAt',
    'updatedAt',
    'correlationId',
    '_id',
    'latencyMs'
  ]);

  /**
   * Sanitizes object by stripping non-deterministic runtime fields and masking PII.
   */
  public static sanitizeObject(obj: any, options: CharacterizationOptions = {}): any {
    if (obj === null || obj === undefined) return obj;
    if (typeof obj !== 'object') return obj;

    const ignored = new Set([...this.defaultIgnoredKeys, ...(options.ignoredKeys || [])]);

    if (Array.isArray(obj)) {
      return obj.map((item) => this.sanitizeObject(item, options));
    }

    const sanitized: Record<string, any> = {};
    for (const key of Object.keys(obj)) {
      if (!ignored.has(key)) {
        sanitized[key] = this.sanitizeObject(obj[key], options);
      }
    }

    // Apply PII masking (default: true for compliance)
    return options.maskPii !== false ? PiiMasker.maskObject(sanitized) : sanitized;
  }

  /**
   * Compares legacy V1 response with modern V2 response and returns precise discrepancy list.
   */
  public static compareResponses(
    legacyRes: { status: number; body: any },
    modernRes: { status: number; body: any },
    options: CharacterizationOptions = {}
  ): ComparisonResult {
    const differences: string[] = [];
    const statusMatch = legacyRes.status === modernRes.status;

    if (!statusMatch) {
      differences.push(`Status mismatch: Expected ${legacyRes.status} (legacy), got ${modernRes.status} (modern)`);
    }

    const cleanLegacy = this.sanitizeObject(legacyRes.body, options);
    const cleanModern = this.sanitizeObject(modernRes.body, options);

    const legacyStr = JSON.stringify(cleanLegacy);
    const modernStr = JSON.stringify(cleanModern);

    if (legacyStr !== modernStr) {
      differences.push(`Payload mismatch:\nLegacy: ${legacyStr}\nModern: ${modernStr}`);
    }

    return {
      matches: statusMatch && differences.length === 0,
      statusMatch,
      differences
    };
  }
}

/**
 * Enterprise PII Masker & Data Redaction Engine.
 * Enforces KVKK, GDPR, and PCI-DSS compliance before any test snapshot or log hits disk.
 */
export class PiiMasker {
  private static readonly PAN_REGEX = /\b(?:4[0-9]{12}(?:[0-9]{3})?|5[1-5][0-9]{14}|3[47][0-9]{13}|3(?:0[0-5]|[68][0-9])[0-9]{11}|6(?:011|5[0-9]{2})[0-9]{12}|(?:2131|1800|35\d{3})\d{11})\b/g;
  private static readonly IBAN_REGEX = /\b[A-Z]{2}[0-9]{2}[A-Z0-9]{4}[0-9]{7}([A-Z0-9]?){0,16}\b/g;
  private static readonly TCKN_REGEX = /\b[1-9][0-9]{10}\b/g;
  private static readonly EMAIL_REGEX = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g;
  private static readonly SENSITIVE_KEY_REGEX = /^(?:password|secret|token|authorization|apiKey|cvv|pin)$/i;

  public static maskString(value: string): string {
    if (!value || typeof value !== 'string') return value;
    let masked = value;
    // Mask Credit Card Numbers (preserve last 4)
    masked = masked.replace(this.PAN_REGEX, (pan) => `****-****-****-${pan.slice(-4)}`);
    // Mask IBANs (preserve first 4 and last 4)
    masked = masked.replace(this.IBAN_REGEX, (iban) => `${iban.slice(0, 4)} **** **** ${iban.slice(-4)}`);
    // Mask 11-digit National Identity (TCKN)
    masked = masked.replace(this.TCKN_REGEX, (id) => `${id.slice(0, 3)}*****${id.slice(-2)}`);
    // Mask Email addresses
    masked = masked.replace(this.EMAIL_REGEX, (email) => {
      const [local, domain] = email.split('@');
      return `${local.charAt(0)}***@${domain}`;
    });
    return masked;
  }

  public static maskObject(obj: any): any {
    if (obj === null || obj === undefined) return obj;
    if (typeof obj === 'string') return this.maskString(obj);
    if (typeof obj !== 'object') return obj;

    if (Array.isArray(obj)) {
      return obj.map((item) => this.maskObject(item));
    }

    const result: Record<string, any> = {};
    for (const [key, value] of Object.entries(obj)) {
      if (this.SENSITIVE_KEY_REGEX.test(key)) {
        result[key] = '[REDACTED]';
      } else if (typeof value === 'string') {
        result[key] = this.maskString(value);
      } else {
        result[key] = this.maskObject(value);
      }
    }
    return result;
  }
}

export interface ServiceResponseEnvelope<T> {
  success: boolean;
  data?: T;
  meta?: Record<string, unknown>;
  error?: {
    code: string;
    message: string;
    details?: unknown;
  };
}

export class ApiError extends Error {
  public readonly code: string;
  public readonly details?: unknown;
  public readonly status: number;

  constructor(message: string, code: string = 'API_ERROR', status: number = 400, details?: unknown) {
    super(message);
    this.name = 'ApiError';
    this.code = code;
    this.status = status;
    this.details = details;
  }
}

export class ApiClient {
  private baseUrl: string;

  constructor(baseUrl: string = '{{API_BASE_URL}}') {
    this.baseUrl = baseUrl.replace(/\/+$/, '');
  }

  private getHeaders(): Record<string, string> {
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
      'x-correlation-id': `web_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`
    };
    const token = localStorage.getItem('auth_token');
    if (token) {
      headers['Authorization'] = `Bearer ${token}`;
    }
    return headers;
  }

  private async request<T>(endpoint: string, options: RequestInit = {}): Promise<T> {
    const url = endpoint.startsWith('http') ? endpoint : `${this.baseUrl}${endpoint.startsWith('/') ? '' : '/'}${endpoint}`;
    const response = await fetch(url, {
      ...options,
      headers: {
        ...this.getHeaders(),
        ...(options.headers as Record<string, string> | undefined)
      }
    });

    // The body is JSON or empty; an empty or non-JSON body leaves the payload null.
    const payload = (await response.json().catch(() => null)) as (Partial<ServiceResponseEnvelope<T>> & { message?: string }) | null;

    if (!response.ok) {
      const errMessage = payload?.error?.message || payload?.message || `HTTP ${response.status} Request Failed`;
      const errCode = payload?.error?.code || 'HTTP_ERROR';
      throw new ApiError(errMessage, errCode, response.status, payload?.error?.details);
    }

    // Handle ServiceResult<T> envelope automatically
    if (payload && typeof payload === 'object' && 'success' in payload) {
      if (!payload.success) {
        throw new ApiError(
          payload.error?.message || 'Operation failed',
          payload.error?.code || 'OPERATION_FAILED',
          response.status,
          payload.error?.details
        );
      }
      return payload.data as T;
    }

    return payload as T;
  }

  public get<T>(endpoint: string): Promise<T> {
    return this.request<T>(endpoint, { method: 'GET' });
  }

  public post<T>(endpoint: string, body?: unknown): Promise<T> {
    return this.request<T>(endpoint, {
      method: 'POST',
      body: body !== undefined ? JSON.stringify(body) : undefined
    });
  }

  public put<T>(endpoint: string, body?: unknown): Promise<T> {
    return this.request<T>(endpoint, {
      method: 'PUT',
      body: body !== undefined ? JSON.stringify(body) : undefined
    });
  }

  public delete<T>(endpoint: string): Promise<T> {
    return this.request<T>(endpoint, { method: 'DELETE' });
  }
}

export const apiClient = new ApiClient();
